// Cluster competitor reviews into objection patterns.
// Real implementation should use embeddings + clustering. This skeleton
// groups verbatim 1–3-star reviews by similar opening phrases.
const reviews = items.flatMap(i => i.json.reviews || []);
const grouped = {};
for (const r of reviews) {
  const key = (r.body || '').toLowerCase().slice(0, 60);
  if (!key) continue;
  if (!grouped[key]) {
    grouped[key] = { quote: r.body, source_asin: r.asin, stars: r.star_rating, frequency: 0 };
  }
  grouped[key].frequency += 1;
}
const objections = Object.values(grouped)
  .sort((a, b) => b.frequency - a.frequency)
  .slice(0, 20);
const incomingAsin = $('Webhook').first().json.body.asin;
return [{ json: { asin: incomingAsin, objections } }];
